uses db;

loadModule("lib/config.prg");

var cfg = loadConfig("");
var dbFile = file.absolute(cfgGet(cfg, "db.path", "private_data/ozon/ozon.sqlite"));
var currentUrl = "";
var currentProductId = "";
var currentTrackingEnabled = true;

db.connect(db.QSQLITE, dbFile);

if (!db.active)
    throw "Не удалось подключиться к SQLite: " + dbFile;


// ============================================================
// Создание и миграция таблицы products
// ============================================================

var productsSchema = db.query();

productsSchema.execSQL(
    "create table if not exists products (" +
    "source text, " +
    "product_id text, " +
    "name text, " +
    "brand text, " +
    "best_url text, " +
    "status text, " +
    "created_at text, " +
    "updated_at text, " +
    "primary key(source, product_id))"
);

productsSchema.close();


// Проверяем наличие поля thumbnail

var thumbSchema = db.query();
thumbSchema.open("pragma table_info(products)");

var hasThumb = false;

while (!thumbSchema.eof())
{
    if (str.toString(thumbSchema.field(1)) == "thumbnail")
        hasThumb = true;

    thumbSchema.next();
}

thumbSchema.close();


// Добавляем поле, если оно отсутствует

if (!hasThumb)
{
    var migrate = db.query();

    migrate.execSQL(
        "alter table products add column thumbnail blob"
    );

    migrate.close();
}


// ============================================================
// Настройка изображения товара
// ============================================================
form.thumbLabel.styleSheet = "QLabel { border: 1px solid #d9e1ea; background: white; }";
form.thumbLabel.text = "Нет фото";

var trackingSchema = db.query();
trackingSchema.open("pragma table_info(products)");
var hasTrackingEnabled = false;
var hasFavoriteState = false;
while (!trackingSchema.eof())
{
    var columnName = str.toString(trackingSchema.field(1));
    if (columnName == "tracking_enabled")
        hasTrackingEnabled = true;
    if (columnName == "favorite_state")
        hasFavoriteState = true;
    trackingSchema.next();
}
trackingSchema.close();
if (!hasTrackingEnabled)
{
    var addTrackingColumn = db.query();
    addTrackingColumn.execSQL(
        "alter table products add column tracking_enabled integer not null default 1"
    );
    addTrackingColumn.close();
}
if (!hasFavoriteState)
{
    var addFavoriteStateColumn = db.query();
    addFavoriteStateColumn.execSQL(
        "alter table products add column favorite_state text not null default 'unknown'"
    );
    addFavoriteStateColumn.close();
}

// ============================================================
// Отображение информации о товаре
// ============================================================

function thumbLabel_linkActivated(Sender, href)
{
    var link = str.toString(coalesce(href, ""));
    if (str.startswith(link, "https://www.ozon.ru/product/"))
        qt.openUrl(link);
}



function showProduct(rowIndex)
{
    if (rowIndex == null or rowIndex < 0)
        return;


    // Получаем данные товара

    var q = db.query();

    q.open(
        "select product_id, name, coalesce(brand, ''), " +
        "coalesce(status, ''), coalesce(best_url, ''), thumbnail, coalesce(tracking_enabled, 1), coalesce(favorite_state, 'unknown') " +
        "from products " +
        "where source = 'ozon' " +
        "order by name collate nocase " +
        "limit 1 offset " + str.toString(rowIndex)
    );

    if (q.eof())
    {
        q.close();
        return;
    }

    var id = str.toString(q.field(0));
    var name = str.toString(q.field(1));
    var brand = str.toString(q.field(2));
    var state = str.toString(q.field(3));

    currentUrl = str.toString(q.field(4));

    var thumbBytes = q.field(5);
    currentProductId = id;
    currentTrackingEnabled = (q.field(6) != 0);
    var favoriteState = str.toString(q.field(7));

    q.close();

    form.trackingButton.enabled = true;
    form.trackingButton.text = currentTrackingEnabled
        ? "Не отслеживать"
        : "Возобновить";

    // Ссылка на карточку доступна и при отсутствии миниатюры.
    form.thumbLabel.clear();
    form.thumbLabel.textFormat = 2;
    form.thumbLabel.textInteractionFlags = 4;
    form.thumbLabel.openExternalLinks = false;

    if (currentUrl != "")
    {
        var imageHtml = "<a href=\"" + currentUrl + "\">";

        if (thumbBytes != null)
        {
            imageHtml = imageHtml + "<img width=\"96\" height=\"96\" alt=\"Нет фото\" src=\"data:image/png;base64,"
                + thumbBytes.base64() + "\">";
        }
        else
        {
            imageHtml = imageHtml + "Нет фото";
        }

        imageHtml = imageHtml + "</a>";
        form.thumbLabel.text = imageHtml;
    }
    else
    {
        form.thumbLabel.text = "Нет фото";
    }


    var idQ = str.quoted(id);
    var p = db.query();

    p.open(
        "select captured_at, price " +
        "from price_points " +
        "where source = 'ozon' and product_id = " + idQ + " " +
        "order by captured_at desc, id desc " +
        "limit 1"
    );

    var at = "Нет истории";
    var lastPrice = null;

    if (!p.eof())
    {
        at = str.toString(p.field(0));
        lastPrice = p.field(1);
    }

    p.close();


    // Формируем карточку товара

    form.card.text =
        name + "\n" +
        (brand == "" ? "Бренд не указан" : brand) + " • " + state + "\n" +
        "Текущая цена: " +
        (lastPrice == null
            ? "нет данных"
            : format("%.2f", lastPrice) + " ₽") +
        " • " + at + "\n" +
        "ID: " + id;

    // Переход на товар доступен по клику по thumbLabel.


    // ========================================================
    // Получение истории изменения цены
    // ========================================================

    var h = db.query();

    h.open(
        "select price from (" +
        "select price, captured_at, id " +
        "from price_points " +
        "where source = 'ozon' and product_id = " + idQ + " " +
        "order by captured_at desc, id desc " +
        "limit 60" +
        ") " +
        "order by captured_at asc, id asc"
    );

    var prices = #[];
    var low = 0.0;
    var high = 0.0;

    while (!h.eof())
    {
        var v = h.field(0);

        if (v != null)
        {
            prices.push(v);

            if (prices.size() == 1 or v < low)
                low = v;

            if (prices.size() == 1 or v > high)
                high = v;
        }

        h.next();
    }

    h.close();


    // ========================================================
    // Формирование графика изменения цены
    // ========================================================

    if (prices.empty())
    {
        form.chart.text =
            "Для товара нет сохранённых точек изменения цены.";
    }
    else
    {
        var bars = #["▁", "▂", "▃", "▄", "▅", "▆", "▇", "█"];
        var line = "";

        for (var i = 0; i < prices.size(); i++)
        {
            var level = 3;

            if (high > low)
            {
                var ratio = (prices[i] - low) / (high - low);

                if (ratio < 0.125)
                    level = 0;
                else if (ratio < 0.25)
                    level = 1;
                else if (ratio < 0.375)
                    level = 2;
                else if (ratio < 0.5)
                    level = 3;
                else if (ratio < 0.625)
                    level = 4;
                else if (ratio < 0.75)
                    level = 5;
                else if (ratio < 0.875)
                    level = 6;
                else
                    level = 7;
            }

            line += bars[level];
        }

        form.chart.text =
            "ДИНАМИКА ЦЕН • " + str.toString(prices.size()) + " точек\n" +
            line + "\n" +
            "Минимум: " + format("%.2f", low) + " ₽    " +
            "Максимум: " + format("%.2f", high) + " ₽";
    }


    // Обновляем статус

    form.statusLabel.text = "Выбран товар: " + name;
}


// ============================================================
// Обработчики событий формы
// ============================================================

function trackingButton_clicked(Sender, checked)
{
    if (currentProductId == "")
        return;

    currentTrackingEnabled = !currentTrackingEnabled;
    var trackingValue = currentTrackingEnabled ? 1 : 0;
    var updateTracking = db.query();
    updateTracking.execSQL(
        "update products set tracking_enabled = ? where source = 'ozon' and product_id = ?",
        #[trackingValue, currentProductId]
    );
    updateTracking.close();

    form.trackingButton.text = currentTrackingEnabled
        ? "Не отслеживать"
        : "Возобновить";
    form.productsGrid.refresh();
    form.statusLabel.text = currentTrackingEnabled
        ? "Отслеживание товара возобновлено"
        : "Товар исключён из отслеживания; история сохранена";
}

function productsGrid_currentRowChanged(Sender, rowIndex)
{
    
    showProduct(rowIndex);
}

form.thumbLabel.linkActivated = thumbLabel_linkActivated;
form.trackingButton.clicked = trackingButton_clicked;
